INSERT INTO `campus_news` VALUES ('2026103001', '聚焦AI算力集群光电融合技术 哈工大首届集成电路产学研合作论坛举行','2026-10-30','https://www.hitsz.edu.cn/_upload/article/images/9d/b8/2e45e70c47e0a16bf54b042eed1b/906812ec-b23e-4fc5-9589-cdb7ad3d89fc.jpg','【哈工大（深圳）宣】（向碧霞 石冰若 文/图）10月28日，哈工大首届集成电路产学研合作论坛在深圳大学城国际会议中心举行。论坛以“AI算力集群光电融合技术”为主题，邀请来自芯片、半导体、光通信和光电技术等领域的产业界专家、企业代表与高校师生相聚一堂，围绕光模块、CPO等技术进展与产业趋势，以及联合科研攻关、人才培养、成果转化等校企合作模式展开深入交流，共话发展机遇，共促产学研协同创新。
哈工大党委常委、副校长，深圳校区校长黄玉东，深圳市南山区科创局党组成员、副局长林洋，深圳校区副校长吕宏振出席论坛。华为、壁仞科技、楠菲微电子、粤芯半导体等多家行业龙头与创新企业的技术负责人、高管和师生代表参加论坛。论坛由深圳校区集成电路学院主办，集成电路学院院长宋清海主持。
开幕式上，黄玉东致辞。他指出，伴随人工智能大模型快速迭代，AI算力集群规模持续扩张，带宽、功耗与时延已经成为制约算力系统性能提升的核心痛点，光电融合技术为破解上述难题提供重要路径。推动技术发展，除了关注单个器件指标，也需要打通芯片、封装、光互连等环节协同、更要对接产业需求，这正是产学研合作的意义。高校具备基础研究与前沿探索优势，企业掌握一线产品研发与市场需求，产学研深度融合才能打通从科研探索到产业应用的完整链条。哈工大始终重视科技创新与人才培养，期待以本次论坛为契机，围绕集成电路及光电融合领域加强校企合作，共同为我国集成电路产业高水平科技自立自强贡献力量。
宋清海围绕学科布局、科研方向、人才培养模式等介绍了集成电路学院建设发展情况。他指出，本次论坛旨在搭建开放交流、互通互信平台，期待专家从产业一线分享技术路线、提出真实痛点，学院将与企业对接需求、联合攻关、共育人才、共促成果转化，构建高效协同的产学研创新生态。
在论坛的主题报告环节，企业专家分别结合产业一线实践，介绍AI算力、光互连、光电芯片相关技术进展，剖析产业发展现实痛点，分享产品迭代与技术落地实践经验。本次论坛还设置了两场圆桌讨论。企业专家围绕AI算力集群光电融合技术发展趋势、产业现实需求、校企合作可行路径开展充分交流。现场师生积极提问互动，探讨技术攻关难点，碰撞产学研合作新思路。（审核 张惠屏 陈南坤）
论坛现场
黄玉东致辞
宋清海主持
合影留念');
INSERT INTO `campus_news` VALUES ('2026102801', '生物建造学科体系与研究展望','2026-10-28','https://www.hitsz.edu.cn/_upload/article/images/e0/46/367e95844426b156d7988da7d9ae/127ee340-11ae-4a42-8fe1-773acd26e4ec.png','哈尔滨工业大学（深圳）学术讲座
演讲人Speaker：刘汉龙教授
题目Title:生物建造学科体系与研究展望
时间Date：2026年11月1日 Time：上午10：00 ~ 12：00
地点Venue： 信息楼L0416
内容摘要Abstract：
人类在地球上繁衍生息，建设了无数用于生存的栖息地。从远古时代用来遮风挡雨的原生态简易建筑物，到如今大厦林立、高铁纵横的钢筋混凝土建造物，土木工程建造技术经历了多个时代的更迭。随着全球气候变化和生态环境恶化，传统工程建造中高耗能、高排放、高污染及固废降解难、资源循环难的“三高两难”问题严重阻碍了双碳发展战略的实施和工程建造技术的进步。土木工程建造可持续发展，就必须最大限度地减少对自然资源的消耗和破坏，必须从建筑材料的源头上解决减碳问题。面向国家双碳战略目标，面向世界生物技术科技前沿，面向建筑业转型发展，基于工程建造与生态环境融合的理念，提出了人与自然和谐共生的生物建造概念，阐述了生物建造的内涵，初步构建了生物建造学科体系，围绕微生物建造、植物建造、动物建造和仿生建造4个类别，从生物建造理论、技术、材料、装备和工程案例等方面进行了阐述。围绕队伍建设、人才培养、科学研究、平台建设、学术交流和社会服务等方面，探讨了生物建造学科建设体系和产业化发展前景。
个人简介(About the speaker):
刘汉龙教授，中国工程院院士，重庆大学学术委员会主任，原常务副校长，长江学者特聘教授，国家杰出青年科学基金获得者，国务院学科评议组成员，教育部科技委学部委员，住建部科技委委员，水利部科技委委员，国际土力学与岩土工程学会TC303分会主席，《Biogeotechnics》和《土木与环境工程学报（中英文）》主编。长期从事环境岩土力学与防灾减灾工程领域的教学与科研工作，在高速铁路、高速公路、高土石坝、吹填造陆（岛）及岩土文物保护等领域取得多项重要性成果。获国家技术发明二等奖2项，国家科技进步二等奖1项，国家教学成果二等奖2项。获首届全国创新争先奖、何梁何利基金科学技术奖、光华工程科学技术奖、茅以升土力学与岩土工程大奖、国际IACMAG协会德赛岩土大奖、国家探月工程嫦娥四号任务突出贡献者和重庆市科学技术突出贡献奖等荣誉。发表SCI高水平论文350多篇，出版中英文专著8部，主编国家和行业等标准8部。是2019-2025爱思唯尔中国高被引学者，2024-2025年科睿唯安全球高被引科学家。');
INSERT INTO `campus_news` VALUES ('2026102802', '未来学部召开新闻宣传工作培训交流会','2026-10-28','https://www.hitsz.edu.cn/_upload/article/images/34/8c/1a4b69e34733a0223257c42fe2e1/13ed6093-8f7c-4b20-b942-295ca7bfef50.jpg','为深入学习贯彻习近平文化思想，建强学部宣传工作队伍，提升新闻宣传质量，10月23日，未来学部在国设楼C-203会议室，组织召开新闻宣传工作培训交流会。学部党委副书记张爱书作专题报告，学部各媒体平台负责教职工参加本次培训交流。
张爱书副书记结合学部发展实际与宣传工作面临的新形势新任务作专题报告，梳理了学部新闻宣传工作成效，客观分析当前学部宣传工作存在的不足，并提出三点希望，一是提高站位，牢牢把握正确舆论导向，严格落实“三审三校”制度，做到守土有责、守土尽责。二是勤练内功，持续提升宣传工作能力和水平，把握新闻写作规范，用好新媒体传播载体，丰富宣传形式。三是用心用情，讲好未来学部发展故事，凝聚奋进力量，坚持用事实说话，传递学部声音、展现学部形象，为学部高质量发展营造良好舆论氛围。
交流环节，参会教职工围绕稿件撰写、媒体管理等开展交流研讨，分享工作经验，碰撞思路想法。未来学部党委将持续抓好宣传工作队伍建设，以高质量宣传赋能学部高质量发展。
培训会现场
图文马程程
初审张湘妮
复审朱继任
终审张爱书');
INSERT INTO `campus_news` VALUES ('2026102803', '哈工大（深圳）智能学部与南京理工大学 机械工程学院召开交流座谈会','2026-10-28','https://www.hitsz.edu.cn/_upload/article/images/2e/5f/6a6412f642908323264e29091dc5/a9d89e85-d062-4e44-aeb9-612d472f0909.jpg','哈工大（深圳）智能学部与南京理工大学
机械工程学院召开交流座谈会
【哈工大（深圳）宣】（张子薇/文、图）
为进一步落实立德树人根本任务，促进高校育人经验交流，10月20日上午，南京理工大学机械工程学院党委副书记、纪委书记李鹏飞一行5人赴哈尔滨工业大学（深圳）参访，与智能学部通过校园参观、展馆走访和座谈研讨，交流育人理念与学生工作实践经验。
南京理工大学机械工程学院一行参观了校训石、火箭广场及主楼综合展馆。展览将学校发展历程与办学实践相结合，使参观人员对哈尔滨工业大学（深圳）的办学传统、科研特色和育人环境有了更加直观的认识。
参观主楼综合展馆
校园参观后，双方在主楼H613会议室举行人才培养工作交流座谈会，由智能学部党委副书记吴菁主持，双方学生工作相关负责人及辅导员代表参加。智能学部简要介绍整体情况及特色工作后，双方围绕本科学风建设体系、支部建设培训体系、科创竞赛组织经验和高质量就业服务体系四个方向展开交流，结合各自育人实践分享思路与做法，探讨学生教育管理服务工作的开展。
双方开展座谈交流
此次参访将校园文化与办学成果的实地了解，同人才培养工作经验的交流相结合，为双方学习借鉴育人理念、拓宽工作视野搭建了平台，促进了两校相关院系之间的沟通互鉴。
与会人员合影');
INSERT INTO `campus_news` VALUES ('2026102701', '未来学部高新院赴众包物流开展跨境电商专题调研','2026-10-27','https://www.hitsz.edu.cn/_upload/article/images/a1/b8/7d3c024846ea96aec29fb173bc45/d7663832-c58d-45e2-a179-cd0ddf26b302.jpg','10月22日，未来学部高质量发展与新结构研究院（高新院）执行院长周豫教授带队，组织高新院部分特聘专家以及2026级本科生跨境电商课题组成员，前往深圳市众包物流科技有限公司开展实地调研座谈。座谈现场
座谈会上，众包物流总经理甘建军详细介绍企业发展历程、主营业务以及在跨境物流领域的实践探索。与会专家、学生与企业代表围绕跨境电商、跨境物流行业当下遇到的难点、痛点与堵点问题展开充分交流，针对行业现实困境共同研讨可行应对举措，从产业实践、学术研究等不同角度交换观点，碰撞思想，为行业高质量发展建言献策。参与调研的大一本科生课题组成员近距离接触产业一线，直观了解跨境产业真实运行现状，收获实践经验。
本次调研是高新院青年智库人才培养计划的重要实践项目。该项目坚持“文科与工科联合、教师与学生联合、校内与校外联合、国内与国际学生联合”的四联培养目标，推动在校学生走出校园，对接产业现场，实现理论学习与产业实践相结合。
高质量发展与新结构研究院为广东省普通高校特色新型智库，立足深圳“双区”建设，链接政产学研多方资源，聚焦产业现实问题开展调研与决策咨询研究，促进学术研究与产业实践双向赋能。
参会人员合影留念
图文周 豫
初审马程程
复审朱继任
终审张爱书');
INSERT INTO `campus_news` VALUES ('2026102501', '哈工大深圳校区与中建科工集团有限公司举行交流座谈会','2026-10-25','https://www.hitsz.edu.cn/_upload/article/images/86/e2/1d05d8db43db8291512df14489a1/91640a5f-3c1a-44db-bc59-ba1d3dedfc39.jpg','【哈工大（深圳）宣】（谢梁晖 张韶琛 文/图）10月21日，哈工大深圳校区与中建科工集团有限公司举行座谈会，双方围绕深化校企合作进行交流。哈工大深圳校区党委书记黄中、校长助理俞晓国，中建科工集团有限公司党委副书记、董事王心宁参加座谈会。
黄中对中建科工集团有限公司长期以来给予哈工大深圳校区的关心与支持表示感谢。他说，哈工大与中建科工集团有限公司在服务国家重大战略需求及区域经济社会发展上有着相同的初心和使命。希望双方聚焦人工智能、智慧能源等新领域新赛道，围绕人才培养、科学研究、成果转化、思政活动等领域探索更广阔的合作空间，形成系列合作成果，携手为强国建设、民族复兴伟业提供更有力支撑。
王心宁感谢哈工大及深圳校区长期以来为中建科工集团有限公司发展输入源源不断的人才与科技支撑。他说，中建科工集团有限公司是中国钢结构行业竞争力榜首企业，提供“投资、研发、设计、建造、运营”全过程或核心环节服务。希望校企双方深化全链条对接与合作，在人才培养、科学研究等领域取得更多合作硕果，携手为中国式现代化建设贡献更大力量。
座谈会上，双方围绕校企合作契合点、切入点进行深入交流。
哈工大深圳校区智能学部、学生工作部（处）、教务处、科学技术处、人力资源处相关负责人，中建科工集团有限公司人力资源部、党建工作部等相关负责人参加座谈。（审核 张惠屏 陈南坤）
交流座谈
参观深圳校区综合展馆
合影留念');
INSERT INTO `campus_news` VALUES ('2026102201', '提高科技文章撰写水平与实例分析','2026-10-22','https://www.hitsz.edu.cn/_upload/article/images/8c/ab/0b4ada5c4885a96b41fa35c14969/d9aa1539-054b-4d5e-80b0-056154d9763a.png','哈尔滨工业大学（深圳）学术讲座
演讲人Speaker：刘正白教授
题目Title:提高科技文章撰写水平与实例分析
时间Date：2026年10月23日 Time：下午15：00 ~ 16：00
地点Venue： H403
内容摘要Abstract：
以原创性液滴破碎理论为例，通过以下四点内容系统剖析：
（1）科技文章选题与研究方案设计
（2）研究内容组织与结果分析方法
（3）理论创新提出与论文写作技巧
（4）审稿意见回复及论文修改完善
个人简介(About the speaker):
国家特聘专家，南方科技大学教授,新加坡国立大学兼职教授，国际汽车制造与材料杂志（International Journal of Automotive Manufacturing and Materials）创刊主编。研究方向包括发动机燃烧和零部件设计轻量化。主要成就表现在：提出了液滴变形/表面皱褶破碎的原创性理论，很多专利已经产业化，完成了燃烧学、新能源汽车与智能网联汽车、整车设计与发动机技术、汽车总成设计等学术专著。
曾任大连理工大学教授，美国威斯康星大学客座教授，日本群马大学客座教授，德国爱尔兰跟大学客座教授，美国Navistar Inc.汽车公司高级工程师。东风汽车公司首席总工程师，东风商用车公司总经理助理，东风商用车技术中心副中心长。美国汽车工程师学会燃烧委员会副主席。加拿大温莎大学兼职教授。同济大学兼职教授，博导。');
INSERT INTO `campus_news` VALUES ('2026102101', '智创未来擎使命，笃行争先谱华章｜智能学部第二次研究生代表大会顺利召开','2026-10-21','https://www.hitsz.edu.cn/_upload/article/images/c1/28/f16339024506bf8250bf3f6f8372/4e102262-183e-436a-b5c1-4665815e72e9.jpg','【哈工大（深圳）智能学部宣】（图/孙权 文/王笑清）2026年10月13日，哈尔滨工业大学（深圳）智能学部第二次研究生代表大会在A416召开。智能学部党委副书记吴菁、校区团委、研究生会代表出席会议，智能学部研究生辅导员、学部研究生代表参加会议。
会议内容
本次会议以“智创未来擎使命，笃行争先谱华章”为主题，大会听取和审议了研究生会工作报告、提案工作报告，审议通过研究生会章程及相关决议，选举产生新一届研究生会主席团。
图 1 会议现场
预备会议围绕大会筹备工作、代表资格审查、提案工作及相关会议文件展开。与会代表听取和审议了大会筹备工作报告、研代会代表资格审查报告、研代会提案工作报告，表决通过了预备会议议程、筹备委员会成员名单、主席团、秘书长名单；审议通过了《哈尔滨工业大学（深圳）智能学部研究生会章程（试行）》、正式会议议程、研究生会委员会委员名单、研究生会主席团成员候选人名单、研究生会主席团成员选举办法和监票小组名单。
图 2 预备会议
正式会议在庄严的国歌声中拉开帷幕。研究生会向大会作工作报告，全面回顾过去一年研究生会在深化组织改革、加强思想引领、丰富校园文化生活等方面的工作，期望同学们“满怀饱满热情，努力成为高素质创造性人才”，并对未来工作提出思考与展望。报告审议完毕后，大会表决通过研究生会工作报告、提案工作报告和研究生会章程等相关决议。
图 3 熊志强作《研究生会工作报告》
随后，吴菁老师、曲丰成老师、石璐老师依次为研究生会学生干部、优秀部员颁发聘书及荣誉证书，勉励同学们珍惜荣誉、再接再厉，在服务同学和学部建设中继续发挥积极作用。
图 4 吴菁老师为第一届研究生会主席团成员颁发聘书
大会进入第二届研究生会主席团候选人竞选环节。4名候选人围绕个人简介、工作经历与未来工作设想依次作竞选陈述，并现场答复参会代表提问。经现场投票，大会选举寇红英、王梓治、许焮羽三名同学担任新一届研究生会主席团成员。。
图 5 第二届研究生会主席团成员作表态发言
结语
智能学部第二次研究生代表大会既是对过去一年研究生会工作的回顾与总结，也是新一届研究生会接续奋斗的新起点。会议号召学部青年学子以初心为舵、以实干为帆，做志存高远、勤学善思、勇担使命、笃行不怠的新时代青年学子。大会在全体成员齐唱《哈工大之歌》中落下帷幕。未来，在全体研究生的同心聚力下，智能学部研究生会必将步履不停，携手奔赴更加璀璨的远方。
图 6 研究生会工作人员合影留念
审核：吴菁 曲丰成 石璐');
INSERT INTO `campus_news` VALUES ('2026102102', '未来学部高新院聚焦数据驱动创新与出海知产风控 举办“湾区未来 智汇树讲堂”第2期','2026-10-21','https://www.hitsz.edu.cn/_upload/article/images/6b/58/f08ade9d496ab1546ffa2de99e9c/8ba39c1d-9bfd-4f12-94f0-30afadbbfd93.jpg','10月12日，未来学部深圳高质量发展与新结构研究院（高新院）湾区未来 “智汇树” 讲堂（第2期）活动于M栋903会议室顺利举办。本次活动由高新院、经济管理学院联合主办，高新院特聘研究员、校内师生及社会各界人士参与研讨，活动获得校区和未来学部的大力支持。活动现场
本期讲堂包括两场专题分享。高新院特聘副研究员童丹丹作《基于用户数据驱动的产业升级与企业创新》主题报告。本次分享聚焦数智化背景下，解读中国企业如何实现从运营卓越向技术领先和用户亲密的战略转型，讲解企业提升市场洞察、促进供需匹配与产业升级的路径；结合实践案例，提出企业在数智化背景下识别机会、配置资源的应对策略，为中国企业完成创新路径转换、实现高质量增长提供启发。
童丹丹作主题分享
高新院特聘研究员胡海国带来《企业出海知识产权风险管理与体系构建》专题分享。讲堂聚焦企业出海面临的商标抢注、专利诉讼、TRO冻结等知识产权风险，结合瑞幸、海能达等典型案例与权威数据，系统剖析风险成因，并提出涵盖战略、组织、流程、工具及人才的全方位风控体系与应对策略。
胡海国作主题分享
参会人员围绕数据驱动产业创新、企业海外知识产权风控等现实议题交流探讨，研讨观点将整理归档存入智库素材库，为后续课题研究提供素材支撑。
高新院是广东省普通高校特色新型智库、广东省决策咨询研究基地，依托学校跨学科科研优势汇聚多方智力资源，持续产出咨政报告、政策建议、产业规划等高质量决策咨询成果。湾区未来“智汇树” 讲堂作为智库全新IP，立足粤港澳大湾区，集聚各界人才智慧，培育民间智囊力量，构建扎根湾区、不断迭代发展的智库思想生态。后续湾区未来 “智汇树” 讲座将围绕低空经济、双碳新能源、数字治理、未来产业集群等领域开展活动，博采多方智慧，产出优质咨政成果，助力粤港澳大湾区高质量发展。
图文周 豫
初审马程程
复审朱继任
终审张爱书');
INSERT INTO `campus_news` VALUES ('2026102001', '深圳校区研究团队发布多物理成像计算软件 助力深地深海探测自主可控','2026-10-20','https://www.hitsz.edu.cn/_upload/article/images/62/2b/88ca53a042e9bdf90cb622dfe9b1/d3533c15-c033-4586-81a6-1c26ea9cc455.png','【哈工大（深圳）宣】（前沿学部 文/图）近日，哈工大深圳校区前沿学部李文彬副教授团队与校本部马坚伟教授团队发布两款多物理成像计算软件：水平集方法重力数据界面反演软件、水平集方法重力和全波联合成像软件。两款软件面向深部地球探测中重力反演与联合成像的核心难题，提出了具有自主知识产权的算法方案和软件实现，为我国科学计算软件的自主研发贡献哈工大力量。
深地、深海探测是当前地球科学和资源勘探的重大前沿方向。寻找深部矿产资源、评估海底地质结构，探测行星内部构造，都依赖于地球物理成像技术——“隔着厚重的岩层，看清楚地下究竟有什么”。地球物理成像方法众多，涵盖声、光、电、磁、震等多个分支，研究团队将研究重点瞄向重力反演以及重力与地震波联合反演方法。重力数据能够勘察较大范围、深地、深海的结构，也可用于深空探测和行星科学，帮助科学家探测天体的深层内部结构。然而，重力反演素以病态著称，相应反问题具有极强的不适定性。基于等效源原理，相同的重力观测数据可能对应无穷多种密度分布情形，反演结果存在严重的非唯一性，成像的可靠性难以保证。
水平集方法重力数据界面反演软件正是针对重力反演非唯一性这一核心痛点提出的解决方案。所谓“水平集方法”，可以通俗地理解为：用一条不断演化的曲线（或曲面）去描绘地下异常体的形状边界。这样一来，反演的目标就从难以约束的密度分布，转化为相对明确的界面形态，将计算限制到具有“紧支撑集”的质量分布，在“反问题正确性类”的意义上重获解的适定性。该软件适用于有清晰界面的地质结构，例如海底盐丘、金属矿体、岩浆侵入体、拆离断层、沉积盆地基底界面等的反演成像。相关算法论文发表于《反问题》（Inverse Problems、《地球物理学》（Geophysics）、《逆问题与成像》 （Inverse Problems and Imaging）等国际主流学术期刊。
在此基础上，研究团队进一步攻克重力和地震波全波联合反演难题。重力反演虽有探测深度大、范围广的优势，但单一物理数据的反演存在分辨率有限、细节不够精细等局限性；地震波全波反演则具有高分辨率和高精度的优点，但在复杂地质区域（如断裂带、强反射介质、深层区域等）存在困难。考虑重力和地震波数据的联合反演，能够融合两种成像方法的优势，得到更精确、更可靠的反演结果。联合反演的难点在于如何建立不同反演系统的联系，实现多物理数据的有效融合。
水平集方法重力和全波联合成像软件正是针对这一难点开发的计算工具。该软件运用声波方程刻画地震波数据、积分方程刻画重力加速度异常值，通过地震波全波形数据与垂直方向重力加速度数据的联合反演，同时获取地下目标体的波速函数和密度分布。其核心创新在于采用水平集方法表示界面结构，通过界面来刻画速度和密度参数之间的结构相似性。这就好比两位“医生”同时给地球做检查，一位擅长看整体轮廓，一位擅长看局部细节，水平集界面则是他们之间共享的“同一张底片”，让两类检查结果能够精确对齐、相互印证。研究团队克服困难攻坚，将联合反演算法落地为可使用的软件技术，取得专利、软件著作权等知识产权，形成了具有自主知识产权的软件产品。
当前，我国正大力推进深地、深海探测战略，地球物理计算软件作为连接理论算法与工程应用的桥梁，其自主可控具有重要的战略意义。哈工大研究团队将继续深耕科学计算软件的研发，让好的算法落地，推动基础研究更好地服务技术变革。（编辑 向碧霞 审核 张惠屏 陈南坤）
图1：水平集方法重力数据界面反演软件[简称:LevelSet-GraInv]
图2：水平集方法重力和全波联合成像软件[简称:LevelSet-JointInv]
软件的登记：
李文彬、邓星宇，“水平集方法重力数据界面反演软件[简称:LevelSet-GraInv] V1.0”，软件著作权：2025SR1661337
李文彬、邓星宇、马坚伟、赵健沣，“水平集方法重力和全波联合成像软件[简称:LevelSet-JointInv] V1.0”，软件著作权：2025SR1800617
专利文档和论文：
李文彬、邓星宇、马坚伟、赵健沣，“一种基于地震波全波形和重力数据的联合成像方法及系统”，发明专利：ZL202510179728.3
Xingyu Deng, Jianfeng Zhao, Wenbin Li*, Jianwei Ma*. A level-set structural approach for multi-physics joint inversion using full-waveform and gravity data. Inverse Problems (2025) 41(11): 115010
Wenbin Li, Jianliang Qian. Simultaneously recovering both domain and varying density in inverse gravimetry by efficient level-set methods. Inverse Problems and Imaging (2021) 15(3): 387-413');
INSERT INTO `campus_news` VALUES ('2026102002', '深圳大学生思政领航团在哈工大深圳校区“成团”！千名大学生将走上中小学思政课讲台','2026-10-20','https://www.hitsz.edu.cn/_upload/article/images/89/70/b32c174f40a49b73126dfc7f4c16/57a4b319-3a9a-47f5-a302-72229791a762.jpg','【哈工大（深圳）宣】（邹晨璐 张晓辉/文 深圳市教育局/图）为深入贯彻落实习近平总书记关于学校思政课建设的重要指示精神，深化大中小学思政课一体化育人格局，深圳市委教育工委、深圳市教育局组织实施大中小学生“手牵手”思政领航计划，组建千人规模的大学生思政领航团，结对中小学校开展思政交流活动。日前，大中小学生“手牵手”思政领航计划大学生思政领航团成员培训暨受聘仪式在哈工大深圳校区、深圳北理莫斯科大学举办，为深圳市17所高校1000名大学生思政领航团成员开展岗前培训并颁发聘任证书。
仪式上，三位思政教育领域的专家学者从主题设置、素材挖掘以及活动设计等方面为大学生思政领航团做培训。深圳大学马克思主义学院教授杜磊以“解码深圳创新”为例，介绍了讲好思政课的“金点子”，表示面向中小学生，要注重“讲深、讲活、讲小”三重追求，增强课程设计的针对性。哈工大深圳校区党委宣传部/党委教师工作部副部长陈南坤围绕哈工大深圳校区大中小学思政一体化建设做经验分享，通过拆解大学生讲思政课实践案例，拓展领航团成员关于交流活动设计的多维思路。深圳市教育科学研究院副院长彭红玉做《深圳的光荣与使命》系列读本深度解读，带领大学生思政领航员从熟悉的建筑、街道中发现深圳、了解深圳，为思政课探索提供了丰富的本土素材。
活动现场，思政领航员为干货满满的培训竖起了大拇指。哈工大深圳校区学生于凡表示，课程中“人生最浪漫的事莫过于祖国召唤时，我们正青春！”这句话使她深受鼓舞，她将以青春之名为大中小学思政课一体化建设贡献力量。深圳北理莫斯科大学学生南国衡说，通过学习进一步了解了如何把思政教育“落细落实”，今后他将用更贴近中小学生的方式让思政教育接地气、入人心。深圳职业技术大学学生吴依涵表示，通过培训深刻认识到思政教育是真诚共情而非单向灌输，今后她将努力深挖本土案例，通过讲好深圳故事来讲好中国故事。香港中文大学（深圳）思政领航团带队教师蓝天同样深受触动，他表示，家国情怀与国际视野应当相互促进，今后将继续学习党的创新理论，读懂中国发展实践，将所学所思转化为面向中小学生开展思政交流活动的实际本领。
据悉，深圳市大中小学生“手牵手”思政领航计划以大学生牵手中小学生为核心，以大学生讲思政课为载体，推动高校思政资源向中小学校开放共享，促进大中小学思政育人协同联动。接下来，思政领航团成员将在高校支持下，结合学校资源与自身实践经验设计特色思政课程，进入结对中小学校开展育人交流活动，让思政之花在深圳校园更加芬芳。（编辑 谢梁晖 审核 张惠屏 陈南坤）
活动现场
哈工大深圳校区大学生思政领航团成员合影');
INSERT INTO `campus_news` VALUES ('2026102003', '哈工大深圳校区国际脑机智能研究院牵头的深医专项重大仪器项目启动','2026-10-20','https://www.hitsz.edu.cn/_upload/article/images/ce/65/60738b204b71b97eb48066482daa/f701ede0-c4c9-4fb4-97e1-95a4804cd37b.jpg','【哈工大（深圳）宣】（邓艾嘉 文/图）日前，由哈工大深圳校区国际脑机智能研究院院长、医工学院教授蒋田仔主持的深圳市医学研究专项资金（以下简称“深医专项”）重大仪器设备研制与开发项目“基于量子隧穿磁阻效应的无屏蔽脑磁设备研制”启动会召开。
会上，深圳医学科学院深医专项负责人介绍了专项资金设立背景及重大类型项目管理要求，表示深医专项的重大仪器设备研制与开发项目作为典型的医工交叉、产品导向型的应用转化类项目，将精准对接临床需求、破解临床痛点，形成具备临床应用与产业化推广价值的产品。项目将在指导专家组的指导和监督下严格把控研究方案实施质量，保障各关键节点按期推进，确保全面达成并力争突破既定考核指标。
深圳校区科学技术处、财务处负责人分别介绍了校区科研项目和经费管理相关要求，表示校区作为依托单位，将落实项目管理主体责任，建立健全深医专项重大类型项目管理配套制度，为项目规范实施与高质量推进提供坚强保障。蒋田仔教授详细介绍了项目总体目标、研发任务和实施方案。合作单位中科搏锐（北京）科技有限公司深圳市第二人民医院相关负责人分别介绍各自单位承担的研发任务。
项目指导专家对本项目的意义、科学价值和应用前景给予高度评价，认为当前脑磁图在医院应用中面临成本高、不便携等关键瓶颈，极大限制了其应用场景与范围，本项目研发的新一代便携式脑磁图脑认知研究、脑疾病检测和闭环脑机接口等领域具有很大的优势，在深空和深海等极端环境下具有巨大应用潜力。
本次启动会标志着项目正式进入实质性实施阶段。该项目是哈工大深圳校区首个牵头承担的深圳市医学研究专项资金重大仪器设备研制与开发项目，对推动无屏蔽脑磁检测技术发展、促进医工交叉创新与成果转化等方面具有重要意义。（编辑 谢梁晖 审核 张惠屏 陈南坤）
会议现场');
INSERT INTO `campus_news` VALUES ('2026101901', '知行研学，空间探微——建筑学本科留学生开展实地调研','2026-10-19','https://www.hitsz.edu.cn/_upload/article/images/c5/44/8c4fca7947058d0b7210d51380c0/773d7631-00b7-47ee-9318-d9babb531e5f.png','10月16日，建筑学本科三年级留学生在《建筑设计C》授课教师组的带领下，赴南方科技大学医学院学生宿舍开展现场走访与案例研学活动，本次实地调研是《建筑设计C》课程的现场教学环节。南方科技大学医学院学生宿舍在紧凑交通组织、公共交往空间、采光通风等方面具有典型示范意义。抵达现场后，师生依次走访居住单元、共享空间、配套服务用房与室外场地，从功能布局、尺度感知、材料构造、使用者行为需求等角度展开现场讲解。师生围绕集体宿舍的公共与私密边界、高密度居住的舒适性平衡等议题展开现场研讨，引导留学生从使用者视角理解居住建筑设计逻辑，将课堂所学的空间设计理论落实到真实建成场景中，这是现场研学的第二站。
前期，部分建筑学本科留学生参观了位于龙岗云中心的住建部全屋智能重点实验室，助力建筑学留学生直观认识建筑空间与全屋智能一体化的前沿实践，拓展智能人居设计视野。作为现场研学第一站，依托方舟壹号多类型实景样板场景，留学生深入理解我国“好房子” 建设、适老化与数字化居住空间的发展思路，提升留学生专业实践能力与跨文化空间解读能力。
建筑设计教学强调“在现场学习建筑”。后续《建筑设计C》课程将继续坚持 “课堂讲授+实地调研+设计创作” 一体化教学模式，持续组织留学生开展各类建成案例走访。依托系列现场研学，进一步完善国际化建筑学人才培养路径，鼓励国际学生以多元视角观察、解读中国当代建筑实践，在专业训练的同时促进中外建筑文化交流，提升来华留学生专业培养质量与国际教育成效。
图文马 航
初审马程程
复审朱继任
终审张爱书');
INSERT INTO `campus_news` VALUES ('2026101902', '夏吾炯、郭林教授研究团队在有机光电化学合成领域取得新进展','2026-10-19','https://www.hitsz.edu.cn/_upload/article/images/0d/7e/00ef14b7488596dee2cc26164910/c368a196-8009-4060-97da-0edbda25cdb5.png','【哈工大（深圳）宣】（郭林 文/图）日前，哈工大深圳校区前沿学部理学院夏吾炯教授和郭林教授团队在有机光电化学合成研究领域取得新进展。团队研究了一种过渡金属铁-镍双催化的光电化学平台，可直接利用羧酸、醇和醛等天然官能团作为烷基自由基前体，在无需预活化的情况下实现多类型C(sp3)–C(sp3)交叉偶联反应。研究成果以《利用原生官能团实现光电协同促进的C(sp3)–C(sp3)交叉偶联》（Photoelectrochemical C(sp3)–C(sp3) Cross-Coupling using Native Functional Groups）为题发表于《自然合成》期刊（Nature Synthesis）。
自由基–自由基交叉偶联是构建饱和C(sp3)–C(sp3)键的重要策略，在药物分子、天然产物及功能有机材料的合成中具有广泛应用前景。然而这类反应通常面临两个相互关联的挑战：一方面，烷基自由基具有较高的反应活性和较短的寿命，不同自由基在体系中同时生成后，容易发生无选择性的自由基自偶联、歧化等副反应，难以实现精准的交叉偶联；另一方面，近年来虽然有研究报道过渡金属镍催化剂的参与能够有效促进自由基的交叉偶联，但镍催化剂的催化活性高度依赖于其所处的氧化还原环境，阴极过度还原可能导致活性镍物种被进一步还原，进而扰乱正常的催化循环。因此如何在同一反应体系中实现不同烷基自由基的稳定、可控生成，并同时对镍催化剂的氧化态进行精准调控，是发展高效、通用的C(sp3)–C(sp3)交叉偶联反应需要解决的关键问题。
针对这一难题，研究团队提出了“自由基生成与金属催化剂氧化还原调控相互解耦”的研究策略，将原本相互耦合的两个过程进行功能分工。具体而言，利用光照激发铁配合物发生配体到金属电荷转移（LMCT）过程，实现烷基自由基的可控生成；与此同时，借助电化学过程调节反应体系的整体氧化还原环境，为金属催化循环提供稳定的电子条件；在此基础上，通过镍催化剂对不同自由基进行选择性分选，并进一步促进C(sp3)–C(sp3)键的形成。该策略使光化学负责“产生自由基”、电化学负责“调控电子”、镍催化负责“选择性成键”，从而实现了不同反应过程之间的有效协同与相对独立调控。研究进一步发现，体系中引入牺牲性烷基溴化物后，可以有效缓冲阴极区域的强还原环境，避免二价镍被过度还原为一价镍，从而维持镍催化剂处于有利于反应进行的氧化态区间。换言之，烷基溴化物并非简单参与反应的辅助试剂，而是承担了“氧化还原缓冲器”的作用，为镍催化循环提供了更加稳定的电子环境。通过这一设计，研究团队实现了自由基生成、电子转移与镍催化成键过程之间的协调控制，为解决自由基–自由基交叉偶联中长期存在的选择性与催化剂稳定性问题提供了新的思路。
本文第一作者为哈工大深圳校区2022级博士研究生钟平富，通讯作者为哈工大深圳校区理学院夏吾炯教授、郭林教授，哈工大深圳校区是该文第一完成单位和通讯单位。此外，哈工大深圳校区理学院杨超教授也参与了该项目的研究。该工作也得到了国家自然科学基金、广东省自然科学基金、深圳市基础研究等项目的支持。（编辑 谢梁晖 审核 张惠屏 陈南坤）
论文链接：https://www.nature.com/articles/s44160-026-01162-w
图1. 基于光电协同途径的双脱羧偶联反应构建C(sp3)C(sp3)键');
INSERT INTO `campus_news` VALUES ('2026101601', '哈工大（深圳）智能学部学子赴香港中文大学参访交流 ——走进港中大工程学院，近距离感受机器人科技前沿','2026-10-16','https://www.hitsz.edu.cn/_upload/article/images/0a/a4/fded501d48b692a9fe457eed9aa7/0df7acba-d47d-4720-b8ea-6c4eedb04860.jpg','【哈工大（深圳）智能学部】（孙嘉音 文/图）2026年10月14日，哈尔滨工业大学（深圳）智能学部组织本科生代表赴香港中文大学开展参访交流活动。同学们走进港中大校园，与港中大工程学院师生面对面交流，并实地参观了多个机器人领域实验室，收获颇丰。
图1哈工大（深圳）智能学部师生参访香港中文大学
活动伊始，香港中文大学工程学院副院长（教育）李教授（Prof. Patrick Lee）为同学们介绍了工程学院的整体情况及各研究生项目，涵盖学科方向、培养体系与招生要求等内容，帮助同学们全面了解港中大工程教育的发展布局与国际化的科研环境。
图2工程学院教师介绍学院情况与研究生项目
随后，港中大工程学院机械与自动化工程学系（MAE）为同学们精心安排了专题报告与实验室参观。在CUHK T Stone机器人研究院（CURI）学术楼，同学们分别聆听了四位教授的学术报告并参观了相关实验室。张立教授（Prof. Li Zhang）介绍了微型医疗机器人方向的研究进展，展示了微纳米机器人在精准医疗领域的应用前景；陈翡教授（Prof. Fei Chen）围绕具身智能与人机协作展开讲解，介绍了智能机器人与人类协同作业的最新成果；刘云辉教授（Prof. Yunhui Liu）分享了医疗机器人与物流机器人领域的研究工作，其团队在机器人操作与运动控制方面的深厚积累令同学们印象深刻；刘达铭教授（Prof. Darwin Tat-Ming Lau）则介绍了面向建筑施工与维护的机器人技术，展示了机器人技术在土木工程领域的创新应用。在实验室参观环节，同学们近距离观摩了各类机器人平台与实验装置，包括机器人竞赛团队的备赛现场与具身智能实验平台。实验室师生热情讲解，同学们踊跃提问，现场交流气氛热烈。
图3教授作学术报告，介绍机器人领域最新研究进展
最后，同学们开展了校园参观。漫步于依山而建的港中大校园，同学们感受着这所山城学府深厚的人文底蕴与浓郁的学术氛围。随后，同学们在校园内自由活动，共进晚餐，并与港中大师生继续深入交流。
图4参访团在香港中文大学校园合影留念
本次参访活动为哈工大（深圳）智能学部的同学们提供了一次难得的近距离接触学术前沿的机会，加深了同学们对机器人与智能系统领域研究现状的认识，也增进了两校学子之间的了解与友谊。同学们纷纷表示收获满满，将以此为契机，进一步明确学业规划与科研方向，在智能科技领域砥砺前行。
（审核 张雁 吴菁 朱人珺）');
INSERT INTO `campus_news` VALUES ('2026101501', '深度具身智能：感知-操作-学习','2026-10-15','https://www.hitsz.edu.cn/_upload/article/images/0b/7c/9c7f40fe4db0b8952418ab02d96a/05462bd6-8229-4108-8d37-0c7a5ce8d8e8.png','哈尔滨工业大学（深圳）学术讲座
演讲人Speaker：王煜 教授
题目Title:深度具身智能：感知-操作-学习
时间Date：2026年10月20日 Time：下午16：00 ~ 17：00
地点Venue：L栋304-306室
内容摘要Abstract：
数十年来，人们一直憧憬着能够与执行日常家务琐事的人形家用机器人共同生活。然而，经过多年缓慢的进展后，研究人员现如今似乎已站上突破的关键时刻—新一代机器人的诞生所需的关键技术即将取得重大进步。这些得益于人工智能（AI）的驱动，推动了近期多项研究的突破，使得那些曾将人类与机器人区分开来的复杂任务，如今对机器人而言已变得触手可及。
机器人学习在构建具有通用能力的操控智能体方面取得了令人瞩目的进展。基于基础模型和大量人类演示的解决方案展现出了令人印象深刻的泛化能力，而其他基于预训练视觉/语言模型的解决方案则利用其常识知识实现了多样化的操控能力。本报告将围绕整合新范式展开讨论，探讨如何使机器人能够在开放世界中稳健地执行各种高接触性任务，特别是如何学到高接触交互的知识？需要哪些额外的传感模式？如何扩展数据收集工作？如何使用其他来源，例如人工真实操作？
个人简介(About the speaker):
王煜，戴盟机器人董事长、首席科学家，大湾区大学讲席教授、先进工程学院创始院长。美国卡内基梅隆大学博士。历任美国马里兰大学机械工程系副教授兼系统研究院研究员，香港中文大学机械与自动化工程系教授，新加坡国立大学机械工程系教授，香港科技大学机械与航空航天工程系讲座教授、电子与计算机工程系讲座教授、香港科技大学机器人研究院创始院长，澳大利亚蒙纳士大学机械与航空航天工程系教授、系主任。曾任国家自然科学基金会海外青年学者，国家教育部长江学者讲座教授，国家科技部973计划项目首席专家，曾获国家自然科学二等奖。
王煜教授是美国机械工程师学会（ASME）、香港工程师学会（HKIE）及电气电子工程师学会（IEEE）会士。曾担任《IEEE Transactions on Automation Science and Engineering》主编，并曾担任《Computer-Aided Design》,《Structural and Multidisciplinary Optimization》及《Frontiers of Mechanical Engineering》等期刊编委。');
INSERT INTO `campus_news` VALUES ('2026101502', '张倩、毛俊教授团队在相图热电领域取得新进展','2026-10-15','https://www.hitsz.edu.cn/_upload/article/images/bc/63/659387274ee6bfef4b3f120d946e/78ce921a-df63-49e0-bdd7-82a35f6b8a39.png','【哈工大（深圳）宣】（前沿学部 文/图）近日，哈工大深圳校区前沿学部材料科学与工程学院张倩、毛俊教授团队在相图热电领域取得重要进展，团队通过构建实验相图调控材料缺陷化学和载流子浓度，成功激活锆钴锑（ZrCoSb）半赫斯勒材料中的多价带输运，实现电热输运性能协同优化。研究成果以《相边界工程实现高性能ZrCoSb半赫斯勒材料的多能谷激活》（Phase Boundary Engineering Enables Multivalley Activation for High-PerformanceZrCoSbHalf-Heuslers）为题发表在《美国化学会志》（Journal of the American Chemical Society）上。该研究将相图工程由传统的微结构调控进一步拓展至缺陷化学和电子输运调控，为高性能热电材料的精准调控与性能优化提供了新思路。
热电材料是一种具有广阔应用前景的绿色可持续能源材料，可实现热能与电能之间的直接转换。能带工程是提升热电材料电输运性能的重要手段，其中，通过增加参与载流子输运的能谷数量，可以在保持较高电导率的同时提高塞贝克系数，从而获得高功率因子。锆钴锑具有优异的热稳定性和机械性能，是一种具有应用潜力的p型半赫斯勒热电材料。然而，其价带中的次级Γ能谷与主导输运的L能谷之间存在约0.13 eV的能量差，传统锡（Sn）掺杂又受到掺杂效率和载流子浓度饱和的限制，难以进一步激活Γ能谷。因此，近二十年来p型锆钴锑材料的功率因子一直维持在约30 μW cm-1 K-2的水平。
针对这一问题，研究团队采用平衡合金法构建了1173 K下锆-钴-锑（Zr-Co-Sb）三元体系实验等温截面相图，精准确定了锆钴锑相的成分稳定范围，并依据相边界设计了不同钴（Co）含量的材料组分。研究发现，钴含量不仅影响材料中的本征缺陷，还能够显著调节锡掺杂的有效性。在贫钴条件下，具有电子补偿作用的钴间隙缺陷受到抑制，同时锡受主掺杂更加容易，使锡的掺杂效率由常规条件下的约65%提升至接近100%，空穴浓度达到3.8×1021 cm-3。高载流子浓度使费米能级进一步进入价带，从而在原有8个L能谷参与输运的基础上激活Γ能谷，使参与载流子输运的有效能谷数量由8增加至10，实现多能谷协同输运。最终，贫钴锆钴锑材料的最高功率因子达到40.4μW cm-1 K-2，在300-973 K温度范围内平均功率因子达到37.6μW cm-1 K-2，突破了该体系长期以来的功率因子瓶颈。在此基础上，团队进一步通过钴空位缺陷和铪（Hf）合金化增强声子散射、降低晶格热导率，使优化后的锆铪钴锑材料（Zr0.5Hf0.5Co0.97Sb0.78Sn0.2）在973 K时热电优值（zT）达到1.2。该材料与n型钛锆铪镍锡合金（Ti0.2Zr0.4Hf0.4NiSn0.98Sb0.02）组成半赫斯勒热电发电模块，在温差为673 K时，模块最大转换效率达到约11%，功率密度达到约1.75 W cm-2。该项研究表明，相图工程能够通过调节元素化学势和缺陷形成，实现对掺杂效率、载流子浓度和电子结构的协同调控，为高性能热电材料及器件的开发提供了新的科学依据。
哈工大深圳校区为论文第一完成单位，深圳校区博士后端思晨为论文第一作者（现为南洋理工大学博士后），香港大学博士后姚洪浩、深圳校区尹力教授为共同第一作者。深圳校区张倩教授、毛俊教授、曹峰教授，中国科学院物理研究所王玉梅副研究员和南洋理工大学颜清宇教授为论文通讯作者。深圳校区李孝芳副教授、王晓东副研究员、马晓静、江峰，中国科学院物理研究所王修园、裴泽华，南洋理工大学董金峰以及香港大学陈粤副教授参与相关研究工作。（编辑 谢梁晖 审核 张惠屏 陈南坤）
图1相图工程指导高性能锆钴锑基热电材料与器件开发。（a）构建1173 K下锆-钴-锑（Zr-Co-Sb）三元体系等温截面相图，确定锆钴锑的稳定成分范围及贫钴、化学计量和富钴组分区域；（b）载流子浓度提升激活L和Γ价带能谷并提高功率因子；（c）不同钴含量锆钴锑材料的最大功率因子与载流子浓度关系；（d）300-973 K温度范围内平均功率因子对比；（e）锆钴锑基材料热电优值（zT值）与文献报道结果对比；（f）锆铪钴锑/钛锆铪镍锡热电器件最大转换效率与输出功率密度关系。
论文链接：https://doi.org/10.1021/jacs.6c12433');
INSERT INTO `campus_news` VALUES ('2026101401', '哈尔滨工业大学（深圳）学术讲座：微型电化学能源材料与器件','2026-10-14','https://www.hitsz.edu.cn/_upload/article/images/aa/40/4e2c7fdf4c8f965ab6f91df45f14/3e6e9508-0dbf-42ad-b1c5-69923b5ab218.jpg','Harbin Institute of Technology, SHENZHEN
（发学术小票）
主讲人：吴忠帅
题 目：微型电化学能源材料与器件
日 期：2026年10月15日 时 间：10：00
地 点：哈尔滨工业大学（深圳）,D439
***欢迎各界人士参加***
摘 要：
针对可穿戴与微电子系统用储能器件的重大需求，聚焦微纳电能源化学的关键科学问题，在能源材料化学、微型储能器件等方面开展了系统性原创研究。发明了固相锂化剥离新方法，突破了二维碲化物材料难以宏量制备的国际难题，实现了百克级、分钟级二维碲化物纳米片的一次性最大规模、最快速度制备，研制出与微型电化学储能器件输运机制相匹配的电极材料与电解质材料，建立了关键电极、电解质材料吨级连续化制备平台；发展了高精度光刻与打印微加工集成技术，实现了高精度微电极阵列（0.35 mm2/器件）规模化制备以及电解液精确快速沉积（10000个器件/秒），揭示了离子多方向传质反应机制，构建出高性能、集成化微型储能器件；提出了小尺度下多界面协同调控策略，创制出集能源收集-存储-应用的一体化、全柔性自供电微系统。研究成果显著提升了微型储能用能器件在能量密度、集成度与环境适应性方面的综合性能，为智能微电子与可持续能源体系提供了具有原创性和系统性的解决思路。
报告人简介：吴忠帅，中国科学院大连化学物理研究所首席研究员、能源催化转化全国重点实验室副主任、国家杰出青年科学基金获得者、国家自然科学基金创新研究群体项目（A类）负责人、英国皇家化学会会士、2018-2025年连续八年科睿唯安全球高被引科学家、爱思唯尔“中国高被引学者”、中组部引进海外高层次青年人才。主要从事二维材料化学与微纳电化学能源应用的基础研究。已在Nature、Chem. Soc. Rev.、Nat. Commun.（6篇）、Energy Environ. Sci.（17篇）、Adv. Mater.（23篇）、J. Am. Chem. Soc.（11篇）、Angew. Chem. Int. Ed.（15篇）、Natl Sci. Rev.（15篇）等期刊发表学术论文430余篇，论文被SCI总引56000余次。获国家自然科学奖二等奖（2017，序4）、辽宁省自然科学奖一等奖2次（2022，序1；2015，序4）、中国颗粒学会自然科学一等奖、中国化工学会基础研究一等奖、第十三届辽宁青年科技奖、2025年度侯德榜化工科学技术奖-创新奖、中国石油和化学工业联合会-青年创新奖等科技奖励10余项，获批国际标准1项、国家标准2项。兼任Energy Storage Materials副主编、Applied Surface Science副主编，以及Natl Sci. Rev.、Sci. Bull.、Acc. Chem. Res.、J. Energy Chem.、eScience、SusMat、J. Power Sources、eScience、Interdisciplinary Materials、Engineering、储能科学与技术、Nanomaterials、Carbon Futures、Mater.Res. Express、Energy & Fuel、Mater. Chem. Front.、Physics、Chin.Chem. Lett.、Materials Futures、物理化学学报、Chin. J. Struct. Chem.等国际知名学术期刊编委/青年编委。');
INSERT INTO `campus_news` VALUES ('2026101301', '郭湘闽教授团队在城市气候适应与健康人居环境领域取得重要研究进展','2026-10-13','https://www.hitsz.edu.cn/_upload/article/images/bd/f5/42b3f6f1440b9dc28874134a98a8/d760c656-ade7-4c73-95ca-8960c002ba36.jpg','【哈工大（深圳）宣】（刘悦 文/图）近日，哈工大深圳校区郭湘闽教授团队在城市气候适应与健康人居环境研究中取得新进展。相关成果以“Built-Environment Correlates of Self-Reported Heat-Related Impacts in Not-Hot Cities: Dual-Context Exposure Evidence from Harbin’s Early-Season Heatwave”（非传统炎热城市建成环境与居民自报热相关影响的关联：来自哈尔滨早季热浪的双场景暴露证据）为题，发表于城市可持续发展领域国际顶级期刊《Sustainable Cities and Society》。
气候变化背景下，极端高温正对传统避暑城市的空间建设与居民健康保障提出新的挑战。面向气候适应与健康城市建设需求，团队以哈尔滨早季热浪为切入点，融合居民调查与多源空间数据，从居住和工作、学习双场景出发，探讨城市建成环境与居民热相关影响的关联，为寒冷地区城市提升高温适应能力提供实证依据。研究凸显了街景可视绿化与区域蓝绿空间在城市热适应中的重要价值，提出统筹居民日常活动场所、兼顾区域空间布局与沿街环境品质的规划思路。成果为将热适应与健康需求融入城市更新、公共空间优化及绿色基础设施建设提供了科学参考，对推动以人为本的气候韧性城市建设具有积极意义。
《Sustainable Cities and Society》由Elsevier出版，是城市可持续发展与气候韧性研究领域具有重要国际影响力的学术期刊。哈工大深圳校区为论文唯一完成单位，博士研究生刘悦为论文唯一第一作者，郭湘闽教授为论文唯一通讯作者。该研究得到国家自然科学基金等项目的支持。（编辑 谢梁晖 审核 张惠屏 陈南坤）
郭湘闽教授团队在城市气候适应与健康人居环境领域取得重要研究进展');
INSERT INTO `campus_news` VALUES ('2026101201', '英国和欧洲电网负荷柔性聚合服务——中国低碳技术制造商市场拓展机遇','2026-10-12','https://www.hitsz.edu.cn/_upload/article/images/be/b5/4a50fbd9440b91bd9710acbdd155/2f43aed3-1c3c-4e31-b8e3-24d30091130f.png','哈尔滨工业大学（深圳）学术讲座
演讲人Speaker：刘雄伟博士
题目Title:英国和欧洲电网负荷柔性聚合服务——中国低碳技术制造商市场拓展机遇
时间Date：2026年10月15日 Time：下午14：00 ~ 16：00
地点Venue：H栋611室
内容摘要Abstract：
目前，为实现零碳目标，促进风电与太阳能等新能源发电的大规模增长，电网负荷柔性聚合服务是应对新能源发电周期性、波动性、随机性的关键措施之一。
此次学术交流活动由哈尔滨工业大学（深圳）主办，具体流程如下：
1.未来以风电与太阳能为主的电力系统——挑战与机遇：15分钟
2.英国与欧洲灵活电力市场（Steve Green先生，线上；刘雄伟，线下，Entrust Microgrid英国）：15分钟
3. EnSmartEMS：智慧能源管理服务平台（刘雄伟与季明：深圳微电网公司）：30分钟，含Living Lab演示环节。
4.专题讨论：中国低碳技术制造商如何满足CLF (Consumer-Led Flexibility)需求及英国和欧洲市场拓展机遇（由刘雄伟教授主持，并邀请国内低碳技术制造领域多位领军者参与讨论）：30分钟
5.专家问答环节：30分钟
英国Entrust Microgrid成立于2018年12月，始终致力于开拓智能微电网技术，专注建筑环境智能直流与交流混合微电网（EnSmartMGrid），以及为家庭和企业开发先进的智慧能源管理系统（EMS）。Entrust Microgrid公司目前正在开展三个欧洲研发项目，重点研究电网CLF聚合服务——这是全球能源与电力系统领域，尤其是在欧洲等发达国家，备受关注的核心研发课题之一。
个人简介(About the speaker):
刘雄伟博士是Entrust Microgrid的创始人，在英国、德国及中国拥有超过40多年的学术与工业经验。2016年创立Entrust Microgrid之前，他曾担任坎布里亚大学可持续工程教授及中兰开夏大学能源与电力系统管理教授。目前，刘雄伟先生是哈德斯菲尔德大学客座教授。刘雄伟博士是Entrust直流与交流混合智能微电网、Entrust智能充电系统及Entrust智慧能源管理系统的发明人，拥有四项核心技术专利，并开发了EnSmart系列产品及系统解决方案。');
INSERT INTO `campus_news` VALUES ('2026101001', '哈尔滨工业大学（深圳）学术讲座：高比能电池材料开发与性能优化','2026-10-10','https://www.hitsz.edu.cn/_upload/article/images/27/fe/e5675e984e0f9df3de470ad0728b/ed711160-02db-484d-9ca5-1861fab32fab.png','主 讲 人：张桥保 厦门大学 教授
题 目：高比能电池材料开发与性能优化
日 期：2026年10月16日
时 间：09:30-11:30
地 点：哈尔滨工业大学（深圳） 信息楼L414-415-416
***欢迎各界人士参加 （发放学术小票）***
摘 要：
发展高能量密度、高功率密度和长循环寿命二次电池是当前国内外前沿研究热点，也是能源电化学材料研究的核心。先进电池材料开发是实现高比能二次电池的关键前提，这迫切需要对现有电池材料进行优化并探索新型高性能电池材料，同时借助清晰、精确的先进实验表征手段对新机理、新材料和新设计进行深入探讨，以形成系统的科学认识。
本报告将围绕高比能电池材料开发及性能提升的机理解析而展开，以先进显微和谱学表征为研究手段，深入解析其微观结构与宏观电化学性能间的构效关系，以期为解决目前高比容量电池材料应用于高比能电池存在的瓶颈问题提供新的研究思路。
报告人简介：
张桥保，厦门大学材料学院教授，表界面化学全国重点实验室研究员，国家优秀青年科学基金获得者，国际先进材料协会会士，连续入选科睿唯安全球“高被引科学家”。长期从事高比能二次电池关键电极材料的设计优化，固态电池及其储能过程中的构效关系解析的基础科学和应用研究。共发表SCI学术论文230余篇，引用26000余次，H因子93。以第一或通讯作者(含共同)在Sci. Adv., Nat. Commun., J. Am. Chem. Soc., Adv. Mater., Energy Environ. Sci., Angew Chem Int Ed., Chem. Soc. Rev., Prog. Mater. Sci., Electrochem. Energy Rev., Mat. Sci. Eng. R.等重要学术期刊上发表论文200余篇。曾获湖南省和北京市自然科学二等奖，国际先进材料协会科学家奖，中国新锐科技人物卓越影响奖，Sci. China Mater., J. Mater. Chem. A期刊新锐研究者和厦门大学及福建省高等教育教学成果一等奖等奖项。主编撰写化学工业出版社[电池材料—合成、表征与应用]、[能源材料的原位透射电子显微分析]和[固态电池基础科学和产业实践]书籍三本。主持国家自然科学基金委联合基金重点项目、优秀青年基金项目、重大研究计划项目及国家重点研发计划“课题等国家和省部级项目十余项。现担任Nat. Sci. Rev. (NSR)学科编辑工作组成员，Chin.Chem.Lett.副主编和Rare Metals学术副主编等。');
INSERT INTO `campus_news` VALUES ('2026101002', '生成式人工智能时代下的城市洪涝（Urban Flooding in the Era of Generative AI）','2026-10-10','https://www.hitsz.edu.cn/_upload/article/images/ed/1a/992af7bc40a594a6f963b256a0a0/546ae1c0-86b8-4e79-875c-50c5e5d7a1d2.png','哈尔滨工业大学（深圳）学术讲座
演讲人Speaker：Dragan Savic教授
题目Title:生成式人工智能时代下的城市洪涝（Urban Flooding in the Era of Generative AI）
时间Date：2026年10月22日 Time：上午10：00 ~12：00
地点Venue：E栋425室
内容摘要Abstract：
人工智能技术从早期基于机器学习的数据分析，到快速洪涝模拟与预警系统，再到生成式人工智能与智能体技术的应用，推动了洪涝模拟与管理领域范式的演变。传统城市洪涝模拟高度依赖人工操作，模型配置、运行及结果分析等环节专业知识门槛较高，存在流程复杂、效率受限等问题。基于大语言模型的智能体人工智能（Agentic AI）能够理解自然语言指令，调用预定义功能接口，实现多步骤任务的自动化执行。根据任务组织方式的不同，智能体系统可分为基于技能（Skill-based）、基于工具（Tool-based）和多智能体（Multi-agent）三种架构，分别通过动态调用操作说明、预设功能接口及专业智能体分工协作完成任务。通过比较不同架构的适用场景并探索其组合应用，可构建更加高效、可追溯的城市洪涝模拟工作流程，为城市排水与洪涝管理的智能化转型提供新的技术路径。
个人简介(About the speaker):
DraganSavic（德拉甘·萨维奇），博士，英国埃克塞特大学水信息学教授，英国皇家工程院院士、欧洲科学院院士、国际水协杰出会士，水信息学与智慧水务领域国际知名专家。1990年获得加拿大曼尼托巴大学土木工程博士学位，1994年加入英国埃克塞特大学，1998年共同创立该校水系统研究中心，2001年成为英国首位水信息学教授。2018年出任荷兰KWR水研究所首席执行官，现任该研究所数字科学全球顾问。
主要研究方向包括水信息学、人工智能、水系统优化、智慧水务及城市水资源管理，在供排水系统智能建模、优化调度与数字化管理领域取得突出成果。累计发表学术论文及研究报告400余篇，学术成果被引用超过30000次，2025年荣获美国土木工程师学会Julian Hinds奖。曾任国际水协数字水务计划指导委员会主席、国际水信息学联合委员会主席及Journal of Hydroinformatics主编，现任Cambridge Prisms: Water联合主编，并担任Water and Ecology、River等学术期刊编委。');
INSERT INTO `campus_news` VALUES ('2026101003', '吴文俊奖特等奖哈工大深圳校区张民教授成果入选中国科协“新天工开物”代表性成果','2026-10-10','https://www.hitsz.edu.cn/_upload/article/images/d5/31/c87f68f24801bac1fa8062cc82c0/911844ad-45e7-4f1b-ad02-d4fd2472b07c.jpg','9月30日，中国科协“新天工开物”科技成就发布会人工智能专场首播，哈工大深圳校区特聘校长助理张民教授的成果“深度自然语言理解和生成关键技术及应用”入选中国科协“新天工开物”代表性成果。
自然语言理解与生成，被誉为人工智能领域皇冠上的明珠，全球主要国家视其为战略性关键技术。张民介绍，其带领团队自主研发的“立知”Uni-MoE系列多模态大模型，提出符号主义与连接主义有机融合、以语言为核心的语言智能原生的人工智能新范式，针对复杂语义理解、自然语言生成、跨领域适配等关键问题取得了突破性进展。项目技术已在多家头部企业落地应用，取得显著经济与社会效益，获得2025年度吴文俊人工智能科技进步奖特等奖。
“新天工开物”科技成就发布会是中国科协主办的科技成就教育品牌，聚焦中国具有标志性、战略性、引领性的科技成就，发布技术进步、工程进展、产业进阶，推介战略科学家、一流科技领军人才和卓越工程师等，传播科学家精神、科学精神，彰显新型举国体制优势，服务科技强国建设。（编辑 常溪 审核 张惠屏 陈南坤）');
INSERT INTO `campus_news` VALUES ('2026100801', '刻槽肋FRP筋混凝土结构的研究进展','2026-10-08','https://www.hitsz.edu.cn/_upload/article/images/8f/dc/843e036b4bb3bfe19d19fcbbe318/ebfe989f-8a78-4d78-a477-754d4319516c.png','哈尔滨工业大学（深圳）学术讲座
演讲人Speaker：王震宇 教授
题目Title：刻槽肋FRP筋混凝土结构的研究进展
时间Date：2026年10月9日 Time：15:00-16:00
地点Venue：E425
内容摘要Abstract：
针对刻槽肋FRP纵筋，在制备技术、力学性能、粘结机理、构件受弯及抗震性能等方面开展了系统的试验、理论和设计方法研究。相较于传统缠绕肋FRP纵筋，刻槽肋筋内部纤维平直、无褶皱缺陷，其抗压强度可达自身抗拉强度的80%~90%，从根本上解决了FRP筋受压性能薄弱的问题；棱角分明的机械刻槽肋大幅增强了与混凝土的机械咬合作用，粘结强度较传统凹槽肋FRP筋提升41%~63%，在普通混凝土中粘结强度最高可达24.6 MPa，略高于钢筋；FRP筋足尺梁的受弯试验证实，刻槽肋筋梁在裂缝宽度与变形方面均明显优于传统FRP筋梁；FRP筋混凝土柱的抗震性能试验表明，刻槽肋筋柱在裂后刚度、承载能力、位移延性及累积耗能等方面均展现出显著优势。刻槽肋FRP筋的粘结性能稳定且具备可重复性，为制定统一的复材筋生产与性能标准开辟了可行路径。研究成果丰富了复材筋混凝土结构设计理论，为涉海工程中复材筋的规模化应用提供科学依据与技术支撑。
个人简介(About the speaker):
王震宇，教授、博士生导师，2001年至2021年任教于哈尔滨工业大学土木工程学院，现任烟台大学校学术委员会委员、土木工程学科带头人。主要研究纤维增强复材制品与海洋土木工程，主持完成国家自然科学基金5项、“973”及重点研发计划子课题2项、省部级项目8项；主编及参编标准8部；获华夏建设科学技术二等奖、黑龙江省科技进步二等奖、三等奖。兼任中国复合材料学会土木工程分会常务理事、中国土木工程学会防震减灾工程分会理事等职。发表SCI论文72篇，获美国发明专利2项、国内专利10项，培养博士13人、硕士58人。');
INSERT INTO `campus_news` VALUES ('2026100802', '机制分离驱动的工程结构振动与控制降阶方法','2026-10-08','https://www.hitsz.edu.cn/_upload/article/images/3d/9f/d3dd21c845c0ad160cfc029ba500/4fc65420-72ad-41ef-9b33-1af186016d74.png','哈尔滨工业大学（深圳）学术讲座
演讲人Speaker：苏成 教授
题目Title：机制分离驱动的工程结构振动与控制降阶方法
时间Date：2026年10月10日 Time：15:30
地点Venue：E425
内容摘要Abstract：
工程结构振动与控制涉及多种演化机制的共同作用。基于机制分离策略，提出了面向大型复杂结构振动分析与控制的系列降阶方法，推动了结构非线性动力学理论、随机振动理论与结构控制方法在实际工程中的应用。基于动力系统线性演化机制与非线性演化机制分离，介绍非线性动力系统分析与预测的时域显式降维迭代法和显式物理信息神经网络方法；基于动力系统物理演化机制与概率演化机制分离，介绍线性与非线性结构非平稳随机振动分析的时域显式方法；基于动力系统物理演化机制与控制律优化机制分离，介绍结构振动的显式最优控制方法。以广州南沙大桥、广州万龙大桥、汕头牛田洋大桥、重庆鹅公岩大桥和长沙磁浮快线等国家重大工程项目为应用背景，综述上述机制分离驱动下的系列方法在大型复杂结构随机振动分析、随机优化设计与随机最优控制等方面的研究进展。
个人简介(About the speaker):
苏成，华南理工大学教授，博士生导师，国务院政府特殊津贴专家。2008年-2017年任华南理工大学土木与交通学院院长，现任广州城市理工学院校长、风工程广东高校重点实验室主任。兼任中国振动工程学会第十届理事会常务理事、第九届随机振动专业委员会副主任委员、第七届结构动力学专业委员会副主任委员、第三届全国工程管理专业学位研究生教育指导委员会委员等。担任Journal of Sound and Vibration（Elsevier）、《建筑结构学报》和《应用数学和力学》等期刊编委。主要从事结构随机振动、结构健康监测和计算力学方面的研究，获得中国土木工程詹天佑奖1项、省部级科学技术奖9项、英国土木工程师协会Frederick Palmer奖。教学方面获得高等教育（本科）国家级教学成果奖二等奖1项、广东省教育教学成果奖（高等教育）一等奖1项。');
INSERT INTO `campus_news` VALUES ('2026093001', '未来学部高新院“未来讲堂”首期活动聚焦企业出海与AI赋能资政研究','2026-09-30','https://www.hitsz.edu.cn/_upload/article/images/22/bd/b0c23f9b450a87f9e8dd7e143969/edecd5fb-6c58-4cc6-8979-1c99c606404c.jpg','9月21日，未来学部深圳高质量发展与新结构研究院（高新院）“未来讲堂”首期活动于M栋501会议室顺利举办。本次活动由高新院主办，经济管理学院、致公党深圳市南山区15支部联合承办，高新院特聘专家、校内师生及社会各界人士近30人参与研讨，活动获得校区、学部的大力支持。首期活动由高新院执行院长周豫主持。
活动现场
本期活动包括两场专题分享。深圳市外代国际货运有限公司首席信息官、高新院特聘研究员林家兴作《中国制造型企业出海风险与应对》主题报告，结合2026年对外直接投资最新统计数据，他梳理国内制造企业从产品出海、品牌出海到产业链出海的发展路径，剖析企业出海过程中面临的国内监管、知识产权、ESG合规、数据跨境等多重风险，从地缘合规、产品准入、供应链运营、法律架构等层面给出全流程风控落地方案。同时结合典型案例，参考国内多地护航企业出海的服务模式，提出“稳出海，创新局”发展思路，为制造企业全球化布局提供实务借鉴。
林家兴作主题报告
哈工大（深圳）经济管理学院副教授、高新院院长助理李钰斌带来《AI工具赋能资政报告撰写分享》，结合对策建议、调研报告、风险预警、政策评估等实例，讲解提示词运用、报告框架搭建、事实核验等实操方法，同时指出AI应用存在事实幻觉、数据失真等隐患，强调资政写作必须严守底线，坚持研究者独立判断，扛起研究责任。
李钰斌作主题报告
参会人员围绕产业出海现实痛点、AI赋能资政实操等问题交流探讨，研讨观点将整理归档存入智库素材库，为后续课题研究提供素材支撑。
高新院是广东省普通高校特色新型智库、广东省决策咨询研究基地，依托学校跨学科科研优势汇聚多方智力资源，持续产出咨政报告、政策建议、产业规划等高质量决策咨询成果。“未来讲堂”将升级为智库全新IP——湾区未来“智汇树”讲座，立足粤港澳大湾区，集聚各界人才智慧，培育民间智囊力量，构建扎根湾区、不断迭代发展的智库思想生态。后续湾区未来“智汇树”讲座将围绕低空经济、双碳新能源、数字治理、未来产业集群等领域开展活动，博采多方智慧，产出优质咨政成果，助力粤港澳大湾区高质量发展。
图文胡玉洁、周豫
初审马程程
复审朱继任
终审张爱书');
INSERT INTO `campus_news` VALUES ('2026092801', '2026年全国大学生数学建模竞赛粤琼赛区联合阅卷暨数学建模研讨会在哈尔滨工业大学（深圳）成功举办','2026-09-28','https://www.hitsz.edu.cn/_upload/article/images/3c/71/aaf3b91242b5b4dac0457376262f/7e66e22b-effa-461b-b32d-709dec993988.jpg','9月25日，由哈尔滨工业大学（深圳）前沿学部理学院承办的“2026年全国大学生数学建模竞赛粤琼赛区联合阅卷暨数学建模研讨会”开幕式在深圳大学城国际会议中心举行。哈尔滨工业大学（深圳）副校长李兵教授、前沿学部主任徐成彦教授、理学院副院长梁慧教授、数学学科主任张新明教授；广东省工业与应用数学学会理事长任传贤教授、秘书长洪柳教授；汕头大学校长郝志峰教授；广东工业大学副校长、新疆大学副校长王振友教授；粤港澳应用数学中心主任、广东省运筹学会理事长、中山大学姚正安教授；广东省数学会副理事长、哈尔滨工业大学吴勃英教授，以及各位广东赛区、海南赛区组委会领导、高校评审专家、理事及常务理事、阅卷工作人员等参加了会议。
开幕式由哈尔滨工业大学（深圳）前沿学部理学院副院长梁慧教授主持。梁慧教授对到场各位领导与专家表示热烈欢迎，简要介绍了本次会议的活动背景与主要议程，并预祝本次联合阅卷及研讨会取得圆满成功。
哈尔滨工业大学（深圳）副校长李兵教授首先作了热情洋溢的致辞。他代表学校向参会嘉宾表示热烈欢迎，介绍了学校在数学人才培养与推动数学建模竞赛方面采取的主要举措，并向长期深耕数学建模教学、竞赛组织工作的各位教师致以由衷感谢。他指出，数学建模是连接数学与现实世界的重要桥梁，希望以此次会议为契机，深入学习粤琼兄弟高校在数学建模教学、竞赛组织和人才培养等方面的经验，进一步提升学校数学建模育人水平。
随后，学会理事长、中山大学数学学院副院长任传贤教授代表学会致辞。他首先向全体参会专家和工作人员表达了感谢。他指出，大家主动放弃中秋佳节与家人团圆的机会，积极参与数模阅卷活动，这种无私奉献的精神为本次会议增添了别样的温情。并介绍了今年广东赛区数学建模竞赛的整体情况，总结了赛区在竞赛组织、师资建设、人才培养等方面的工作成效。
接下来，学会秘书长、中山大学洪柳教授主持了新一届理事长、副理事长、常务理事与理事的聘书颁发仪式。特别地，姚正安教授为任传贤教授颁发了新一届理事长聘书。
本次粤琼赛区联合阅卷暨数学建模研讨会期间，同步开展了广东省工业与应用数学学会常务理事会、理事会、竞赛答卷评审、建模教学研讨等系列工作，为粤琼两地数学建模教师搭建了沟通交流平台，将在促进学会发展与区域高校数学建模教学改革、提升竞赛评审质量、夯实创新人才培养根基等方面发挥重要的推动作用。
作为承办单位，前沿学部理学院将以此次会议为契机，进一步加强与粤琼地区高校和相关学术组织的交流合作，持续推进数学建模竞赛与课程教学、创新实践深度融合，以赛促教、以赛促学、赛教融合，不断提升学生运用数学方法解决实际问题的能力，为校区基础学科建设和拔尖创新人才培养注入新动能。');
INSERT INTO `campus_news` VALUES ('2026092802', '张倩、毛俊教授团队在塑性热电材料研究方向取得新进展','2026-09-28','https://www.hitsz.edu.cn/_upload/article/images/97/ad/ff106d814df1b83a81c2cb63bb37/6e7a3862-b4b2-429f-818d-581b738d5561.jpg','【哈工大（深圳）宣】（前沿学部 文/图）近日，哈工大深圳校区前沿学部材料科学与工程学院张倩教授、毛俊教授团队在塑性Mg3(Sb, Bi)2热电材料研究方向取得新进展，实现热电性能与力学性能的协同调控。团队提出通过室温塑性形变技术引入缺陷，并结合退火处理选择性降低位错密度、保留变形孪晶，一方面厘清了位错和孪晶对载流子输运的不同作用，另一方面在热电性能基本恢复至初始水平的同时，显著提升Mg3(Sb, Bi)2材料的强度与硬度。该研究成果以“基于室温塑性形变技术的无机热电材料性能调控”（“Leveraging room-temperature plastic deformation for tailoring inorganic thermoelectrics”）为题，发表于《美国科学院院刊》（Proceedings of the National Academy of Sciences of the United States of America）。
热电材料可以实现热能与电能的直接相互转换，在热能发电和固态制冷等领域具有重要应用前景。然而，传统无机热电材料大多属于共价半导体，普遍存在明显脆性和可加工性差等问题，制约了器件制备与服役可靠性。Mg3(Sb, Bi)2兼具优异热电性能和室温塑性，是突破传统脆性半导体瓶颈的理想体系。但塑性变形会引入位错、孪晶等多种晶体缺陷，各类缺陷如何影响电子和声子输运是塑性热电材料研究中一个有待厘清的关键问题。
针对上述关键科学问题，研究团队选取Mg3.2Sb1.5Bi0.49Te0.01、Mg3.2Sb0.49Bi1.5Te0.01两种典型样品开展相关研究。以Mg3.2Sb1.5Bi0.49Te0.01为例，通过对材料施加0%至15%的室温压缩应变，研究发现塑性变形会显著提升材料内部的位错密度与孪晶比例（图1A-B）。随应变量增加，材料近室温区间电阻率和Seebeck系数显著提升，最终近室温功率因子明显下降（图1C-E）。
为区分位错和孪晶对热电输运性质的影响，团队利用二者热稳定性的差异，对变形样品进行退火处理。经退火处理后，15%应变样品的位错密度大幅下降，而变形孪晶比例基本保持不变。与此同时，材料的近室温电阻率、Seebeck系数和功率因子整体恢复至接近未变形样品的水平（图1C-E）。在三次循环测试中，样品在300 K至773 K温区的平均功率因子均保持在初始值的98%以上，表明样品具有良好的循环稳定性（图1F）。此外，退火后保留的共格孪晶界能够有效阻碍位错运动，从而实现强化作用（图2）。经室温压缩变形（15%应变）和退火处理后，Mg3.2Sb1.5Bi0.49Te0.01和Mg3.2Sb0.49Bi1.5Te0.01的屈服强度分别提高83.4%和37.5%，硬度分别提高28%和17%，同时压缩断裂应变仍接近或高于40%（图1G-I）。
图 1 变形-退火处理协同提升Mg3(Sb, Bi)2热电材料的综合性能。（A-B）不同预应变量样品退火前后的位错密度和孪晶比例；（C-E）无应变样品、15%应变样品及15%应变–退火后样品的电阻率、Seebeck系数和功率因子；（F）多次变形–退火循环后的电输运性能恢复情况；（G）无应变样品与15%应变–退火后样品的工程应力–应变曲线对比，插图为0-5%应变区间的放大图；（H-I）两种组分样品经不同程度预变形和退火后的硬度测试结果。
图 2 变形后Mg3(Sb, Bi)2材料中孪晶与位错的微观结构表征。（A-C）变形孪晶的形貌、界面结构和晶体学取向关系；（D-F）不同衍射条件下的位错成像及消光分析。
哈工大深圳校区为论文第一完成单位。哈工大深圳校区博士研究生张天宇、硕士研究生徐耀为论文共同第一作者，张倩教授、毛俊教授为论文共同通讯作者。哈工大深圳校区陈尚豪、江峰、林晨浩、芝世珍、程谨轩、陈江、吴隆智参与相关研究工作。本工作还得到了哈工大深圳校区曹峰教授、燕山大学赵鹏教授、吉林大学付钰豪教授和实验与创新教育中心姚兆月老师的支持和帮助。该研究得到了国家杰出青年科学基金、广东省基础与应用基础研究基金、国家自然科学基金面上项目等项目支持。（编辑 谢梁晖 审核 张惠屏 陈南坤）');
INSERT INTO `campus_news` VALUES ('2026092301', '智能学部“探能者”职涯实践团走进创维光伏、深圳能源集团 ——探访绿色能源前沿，共话校企合作新篇','2026-09-23','https://www.hitsz.edu.cn/_upload/article/images/1b/6e/7b6ff0d44b18a249ddd65b0e7ed9/68a140f5-bc08-4ce8-b7f0-2c8643f32694.jpg','【哈工大（深圳）智能学部宣】（朱彦玺/图、谢李娜/文）7月23日，智能学部“探能者”职涯实践团走进深圳创维光伏科技有限公司、深能源深能创新技术公司开展参访交流活动。通过展厅、项目参观及座谈交流，深入了解新能源行业发展趋势与企业人才需求，在行走中拓宽视野，在实践中启迪思考。
创维光伏：双向奔赴的深度对话
实践团参观了创维光伏展厅，了解企业发展历程、户用及工商业光伏产品和智慧运维系统。随后参观了办公区域，感受企业文化与工作氛围。
创维光伏展厅——光伏产品展示
参观后双方展开座谈，围绕公司发展、技术创新与人才培养等议题展开交流。创维光伏成立于2020年，拥有四大制造基地和五大产品体系，公司通过线上App及智慧运维平台实现智能管理，并展示了多个零碳实践案例，让同学们直观感受到光伏产业在推动能源转型和可持续发展方面的实际成效。带队老师介绍了学校情况，指出本次参访旨在帮助同学们拓宽视野，在传统建筑行业之外积极寻找新能源等新兴赛道的发展机遇。
创维光伏座谈会
交流中，两位哈工大校友分享了从土木、建筑跨入新能源领域的经历，介绍了公司内部可尝试调岗的发展路径，鼓励同学们跳出学科边界。同学们围绕行业前景与校友代表深入讨论，收获颇丰。针对同学们提出的差异化竞争、亏损应对、人才引进与海外市场等问题，企业代表一一回应，现场氛围热烈。
深圳能源：产学研结合的深度交流
实践团一行参观了深圳能源妈湾电厂品牌项目，与深圳能源集团深能创新技术公司技术专家及研发人员展开深入交流。集团成立于1991年6月，是全国电力行业第一家在深圳上市的大型股份制企业，也是深圳市第一家上市的公用事业股份公司。产业覆盖低碳电力、生态环保、综合燃气和数智服务，实践团就海水制氢及海上风电项目展开深入交流。
深能源座谈会
此次参访让同学们对新能源行业有了更直观、更深刻的理解，拓宽了职业视野。同学们不仅看到了传统学科在新能源领域的广阔应用空间，也增强了拥抱产业变革的信心。
实践团在创维光伏合影留念
实践团在深能源合影留念
审核|吴菁 徐明璇 石璐');
INSERT INTO `campus_news` VALUES ('2026092302', '走进中电技术，共探职涯未来','2026-09-23','https://www.hitsz.edu.cn/_upload/article/images/cf/67/90d8c0d84de3858e9819a3609d89/8088760f-699e-44d7-a66e-d4d33101d1a9.jpg','9月16日下午，智能学部“探能者”职涯实践团走进CET中电技术深圳总部，参加校企交流暨人才开放日活动，通过业务介绍、企业参观、互动答疑和现场面试等环节，深入了解电能管理领域的研发实践与岗位需求。
深圳市中电电力技术股份有限公司创立于1993年，是中国电子信息产业集团有限公司旗下企业，长期深耕电能与能源管理领域。活动伊始，企业工作人员通过宣传片与专题讲解，介绍企业发展历程与整体业务布局。业务介绍环节重点围绕智能电网在线监测、配电网监测与故障诊断等方向展开，结合具体应用场景讲解相关技术对电力系统运行与能源管理的服务价值，并梳理了软件研发、嵌入式、测试、电气设计等岗位在产品研发过程中的职责分工，帮助同学们清晰认知专业知识与产业需求的衔接逻辑。
企业交流与业务介绍现场
在企业工作人员的带领下，实践团参观了企业文化展厅、研发实验室和系统测试中心，结合成果展示与实际业务场景，直观感受了专业知识在技术研发、产品测试中的应用路径。
企业展厅参观
互动答疑环节，同学们围绕 “从校园走向岗位需要做好哪些准备”“如何结合专业背景与个人兴趣选择发展方向” 等问题提问。在企任职的往届校友结合自身求职与工作经历，分享了岗位适应与能力成长的切身心得；企业技术骨干从一线工作视角出发，明确了不同岗位对专业基础、工程实践能力与团队协作素养的具体要求。交流过程中还介绍了入职培训、轮岗实践和导师带教等培养体系，帮助同学们进一步明晰入职后的成长路径。活动同步设置现场面试，同学们可结合自身研究方向与求职意向与企业直接对接。
本次参访融行业认知、职场交流与求职实践于一体，不仅为同学们搭建起连接校园与职场的沟通桥梁，更为大家明晰后续专业学习路径、厘清个人职业发展规划提供了有益借鉴与现实参考。
审核|吴菁 徐明璇韩蕾');
INSERT INTO `campus_news` VALUES ('2026091801', '促进国际交流合作，深圳校区开展国际青年人才来华交流项目','2026-09-18','https://www.hitsz.edu.cn/_upload/article/images/27/af/a0fd108a45fabe0d4facf6744e91/8bf1f986-a691-4354-a236-30278a3cf78c.jpg','【哈工大（深圳）宣】（前沿学部 文/图）为进一步拓展国际科研合作渠道，搭建中外青年科技人才交流桥梁，2026年暑期，在中国国际人才交流基金会国际青年人才来华交流项目（CEP）支持下，来自西班牙巴塞罗那大学和德国德累斯顿工业大学的3名青年科研人员跨越山海，来到哈工大深圳校区，在材料学院王威教授科研团队开展短期工作与国际实习。中外科研青年在思想碰撞中启迪科研灵感，在文化交融中增进彼此情谊，在鹏城之夏书写科学探索、青春共进、跨国相知的交流篇章。
国际青年人才来华交流项目由中国国际人才交流基金会设立，旨在吸引全球青年人才来华进行访问交流、国际实习或短期工作，加深外国青年对中国的认识和了解，推动中外青年在交流中“增进了解、收获友谊、共同成长”，为推动构建人类命运共同体贡献青春和力量。
本次访学以学术互通为核心，三名海外科研人员深度融入课题组科研工作，开展精准化前沿学术交流。巴塞罗那大学博士后研究员Renaud Baillou聚焦微观领域，与课题组师生围绕活性物质、磁性胶体等研究方向深入研讨，依托不同学术思维互补启发、凝聚科研共识。德累斯顿工业大学博士研究生Kelly Henze与Amir Sheikh Shoaei扎根实验一线，围绕片状FeO胶体、SiO-Pt微马达体系开展实验探索，在实操交流中碰撞创新灵感。
走出实验室，他们也在行走与体验中读懂哈工大、感知中国。他们先后走进实验与创新实践教育中心、3D打印实验室，近距离了解学校科技创新成果，感受哈工大百年历史与深圳创新氛围的交融。学术交流之外，温暖的文化互动让跨国友谊悄然生长。中外青年师生以美食为媒，尽情体验烤鸭、火锅、早茶等中国特色美食，在轻松融洽的氛围中增进理解、拉近距离，让本次交流更增添了人文温度。
未来，哈工大深圳校区将坚持国际化办学理念，持续依托各类国际交流项目搭建优质平台，以科研为纽带、以青年为桥梁，深化国际合作交流，助力学校高水平国际化办学再上新台阶。（编辑 谢梁晖 审核 张惠屏 陈南坤）
王威教授（右）带领Amir Sheikh Shoaei（左1）、Kelly Henze（左2）和Renaud Baillou（左3）参观实验室
Kelly Henze与王威教授课题组全体硕博生进行学术交流
Amir Sheikh Shoaei在王威课题组进行显微观察实验
Renaud Baillou与王威教授课题组成员参观哈工大（深圳）3D打印实验室
Kelly Henze参观哈工大深圳校区自主研发无人机（该无人机曾在第二十届中国国际飞行器设计挑战赛中获得全国冠军）
Kelly Henze（左前）和Renaud Baillou（右前）与王威教授课题组于哈工大深圳校区主楼前合影');
INSERT INTO `campus_news` VALUES ('2026091802', '曾瑞教授在电化学促进热化学脱氢制氢研究领域取得重要进展','2026-09-18','https://www.hitsz.edu.cn/_upload/article/images/02/8c/a774727540c1a050b8015cd2d376/64981591-648e-4bc8-9673-b3bc334373d9.png','【哈工大（深圳）宣】（曾瑞 文/图）近日，哈工大深圳校区前沿学部材料科学与工程学院新入职教师曾瑞教授于麻省理工学院工作期间在电化学促进热化学脱氢制氢研究领域取得重要进展。相关成果以《阳极钯膜氢提取强化热化学脱氢反应》（Anodic Pd membrane H2 extraction enhances thermochemical dehydrogenation）为题发表于《自然》（Nature）。该研究提出一种阳极钯膜电化学氢提取策略，在无须氢分压差的条件下实现高温反应体系中的氢气主动分离、纯化与浓缩，并显著促进了氨和甲基环己烷的热化学脱氢过程，为低温高效制氢及氢能储运提供了新的思路。
脱氢反应是燃料加工、化学合成以及氢能储存与运输过程中的关键反应。许多脱氢反应具有强吸热特征，并受到产物氢气的动力学抑制和热力学限制，导致其在中低温条件下反应速率慢、单程转化率低。将脱氢催化剂与氢选择性膜集成，可以通过原位移除产物氢气促进反应进行。然而，传统膜分离主要依赖膜两侧的氢分压差，需要使用真空、吹扫气体或较大的压力梯度，不仅氢通量有限，而且得到的氢气通常处于较低分压状态，后续仍需进行分离与加压。此外，在贫氢条件下，钯膜表面的氢原子复合成氢气过程较为缓慢，进一步限制了传统压力驱动膜的分离效率。
针对上述问题，研究人员设计了一种基于钯膜和水合熔融氢氧化物电解质的中温电化学氢泵。该系统将具有氢选择性的钯基膜同时用作氢传导膜和电化学阳极：脱氢反应生成的氢气首先在钯膜表面解离，氢原子随后穿过膜体，并在外加阳极偏压作用下被氧化为电子和质子；水合熔融氢氧化物中的氢氧根离子作为质子传递介质，将其输送至阴极并重新生成氢气。通过这一过程，系统绕过了传统钯膜渗透侧较为缓慢的氢原子复合步骤，能够利用电化学势主动驱动氢跨膜传输，从而摆脱对膜两侧氢分压差的依赖。与压力驱动方式相比，该策略在300℃下将氢气分离速率提高约4倍，并可把氢气从仅含5%的稀释气流中直接提取并浓缩为常压纯氢气流，实现氢气分离、纯化和浓缩的一体化。
研究人员进一步将该装置与氨分解和甲基环己烷脱氢反应相结合。电化学氢泵能够及时移除反应生成的氢气，减弱产物氢对反应的抑制，使氨和甲基环己烷在250℃下的转化率最高分别达到91%和94%。与传统膜反应器通常需要真空、吹扫气体或更高温度不同，该系统能够在促进脱氢反应的同时直接获得高纯度、高分压氢气，有望减少后续分离和加压环节。
该研究建立了电化学氢提取与热化学催化反应相耦合的新方法。其特点是脱氢反应仍由热催化驱动，电化学装置则作为“氢泵”，持续移除反应生成的氢气，从而促进反应向前进行。该方法有望拓展至其他醇类和烷烃脱氢过程，为氨、液态有机储氢载体等含氢物质的低温高效利用提供新的技术路径。
曾瑞教授为论文第一作者，麻省理工学院Yogesh Surendranath教授为论文通讯作者。曾瑞长期专注于电催化机理、材料设计与合成及原位表征等方向的研究，在国际重要学术期刊发表论文25篇，其中以第一作者或共同第一作者在Nature、Nature Materials、Journal of the American Chemical Society、Science Advances等国际高水平期刊发表论文9篇，2025年入选国家级青年人才，2026年8月全职加盟哈尔滨工业大学深圳校区。（编辑 谢梁晖 审核 张惠屏 陈南坤）
图a，氢气在传统分离和电化学驱动分离过程中的对比示意图；图b，电化学驱动情况下与传统分离（惰性气体吹扫和真空）下氢通量的对比
论文链接：https://doi.org/10.1038/s41586-026-11008-2');
INSERT INTO `campus_news` VALUES ('2026091601', '向海图强丨溯甲午砺初心，向深蓝担使命 ——哈工大（深圳）“尖兵领航”实践团赴大连开展思政实践','2026-09-16','https://www.hitsz.edu.cn/_upload/article/images/d1/a2/e8cdc53d40eda708982ccb0b7e25/e1e2dee1-c24e-471a-81e3-8c7aa6fa64c3.jpg','【哈工大（深圳）宣】（前沿学部 文/图）渤海之滨，黄海之畔。由哈工大深圳校区前沿学部、校区国际教育中心携手组建的哈尔滨工业大学（深圳）“尖兵领航”实践团，于7月25日至8月1日赴辽宁大连开展社会实践，团队由中外学子共同组成，以“溯甲午砺初心，向深蓝担使命”为主题，围绕近代海防历史、重工产业发展、青年人才培育三条主线，开展行走的思政课主题实践。
一、历史镜鉴：回望甲午殇思，铭记海防使命
实践团首站走进旅顺近代历史遗迹群，登临白玉山，重温北洋水师布防与甲午海战史实；在万忠墓纪念馆凭吊遇难同胞，直面近代中国国力孱弱、有海无防的民族苦难；参观旅顺日俄监狱旧址博物馆，铭记殖民压迫史实，“忘战必危、强国强军”的思想共识在每一位队员心中深深扎根。
图1实践团成员在白玉山、旅顺日俄监狱旧址博物馆参观史实展陈
二、重器探访：走进重工一线，见证工业自强
参访大连重工集团，作为国家重机行业重点骨干企业，大连华锐重工集团股份有限公司始建于1914年，累计创造250余项“中国第一”，业务遍及96个国家和地区。在大连港，实践团观摩在建超大型原油轮，直观感受我国超大型船舶建造与远洋航运实力，深化对海洋强国战略产业支撑的认知。
图2实践团在大连华锐重工集团股份有限公司参观生产厂区
三、校地联动：对话青年先锋，凝聚奋进合力
实践团先后对接共青团大连市委员会、大连理工大学与大工西岗数字产业创新园，围绕青年人才政策、校地产业协同等议题开展交流。
在与大连团市委的专题座谈中，双方就青年参与城市发展、基层治理等话题展开深入探讨。
图3实践团成员与大连团市委座谈
在大连理工大学，实践团参观船舶工程学院，了解学科科研布局与青年学者成长，感受高校育人底蕴。
图4实践团在大连理工大学参观交流
实践团还探访了大工西岗数字产业创新园与一二九街街史馆，调研校地共建产业孵化模式，拓宽协同育人路径。
图5实践团成员参观一二九街街史馆
四、以史为鉴向海行，青春奋进正当时
本次实践构建起“历史教育—产业认知—使命践行”的立体化思政链条，累计开展4场专题座谈和多轮深度访谈，积累了丰富的一手调研素材。实践团成员们将传承校训精神，把实践感悟转化为科研动力，立足专业投身国防科技事业，在科技自立自强的征程中践行青年使命。
从甲午殇思到深蓝担当，从百年重工到青春誓言，HITSZer用脚步丈量历史，用行动回应时代。向海图强，未来可期！
图6实践团在大连合影留念');
INSERT INTO `campus_news` VALUES ('2026091401', '未来学部本科生赵君扬在城市科学领域顶刊发表边界效应相关研究','2026-09-14','https://www.hitsz.edu.cn/_upload/article/images/9c/43/e50727b0465a93df210f77b963a8/7a49c2f3-ac42-4fac-aaa2-143ab93dd473.png','近日，哈尔滨工业大学（深圳）未来学部建筑学院2023级本科生赵君扬以第一作者身份，在城市科学领域国际顶级期刊Computers, Environment and Urban Systems发表边界效应相关研究成果。论文题为《基于地理加权加性重力模型与机器学习的城市通勤流边界效应表征——解释框架》（A representation-explanation framework for flow-based border effects on intra-urban commuting using geographically weighted additive gravity model and machine learning）。未来学部建筑学院龚咏喜教授为论文唯一通讯作者。城市中的行政区界、山体、河流和大型基础设施等边界，会不同程度地阻碍人口流动、改变城市空间联系。这种由边界造成的额外空间阻隔被称为“边界效应”，它影响着通勤效率、资源配置和区域协同发展。如何基于人口流动数据精准识别并量化这些空间阻隔，进一步揭示其空间差异及形成机制，是理解城市空间结构、优化跨界联系的重要科学问题。
在前期研究基础上，该研究进一步提出城市边界效应“表征—解释”框架。研究首先利用地理加权加性重力模型，从城市通勤流中提取具有明确距离含义的局部边界厚度，用以量化不同位置边界效应的强弱；在此基础上，进一步结合机器学习方法，分析交通联系、城市功能和自然环境等因素对边界效应空间差异的影响，从而将研究视角从“边界有多强、在哪里更强”推进到“为什么这里的边界更强”。以广州市为例，研究发现行政边界和自然边界均表现出明显的空间差异，公共交通、道路网络、城市功能及自然障碍等因素共同塑造了不同地区的边界阻力。该研究为城市边界效应的定量表征与机制解释提供了新的分析框架，也为城市跨界交通衔接和空间协同治理提供了科学依据。
图1 边界效应的“表征—解释”研究框架
Computers, Environment and Urban Systems是城市科学领域国际顶级期刊。哈尔滨工业大学（深圳）未来学部建筑学院龚咏喜教授团队长期围绕要素流动、城市群空间与边界效应开展研究，已形成从活动空间边界识别、边界效应量化到空间表征与机制解释的系列研究成果，相关成果还发表于Journal of Transport Geography等国际知名期刊。
该研究得到国家自然科学基金和深圳市哲学社会科学规划课题的资助。
此次本科生在顶级期刊发表研究成果，是未来学部建筑学院持续推进本科生科研能力培养、鼓励学生早进课题组、早接触前沿问题的积极成果。
图文龚咏喜
初审马程程
复审朱继任
终审张爱书');
INSERT INTO `campus_news` VALUES ('2026090601', '祝贺！深圳校区博士毕业生王一峰入选中国工业与应用数学学会青年人才托举工程','2026-09-06','https://www.hitsz.edu.cn/_upload/article/images/d1/1e/0949992e4fc88456a6d8d6bc7205/01b87fbb-efea-4950-80b3-d15fda5dd55b.png','【哈工大（深圳）宣】（崔良乐/文 王一峰/图）近日，中国工业与应用数学学会（CSIAM）公布第五届青年人才托举工程项目名单。哈尔滨工业大学深圳校区数学学科博士毕业生王一峰，凭借“基于物理世界模型的深空极端环境模拟”项目，入选国家重大需求攻关项目，成为哈工大数学学科首位入选该工程的博士毕业生。
CSIAM青年人才托举工程面向32岁以下优秀青年科技工作者，重点支持应用数学前沿研究，选拔服务国家重大战略部署、破解“卡脖子”难题、推动社会发展的青年人才。项目实行限额提名和多轮遴选，候选人须经过资格审查、分类初选、现场答辩、专家评议等环节，最终从全国申报人选中择优确定。本届共入选12人，其中攻关项目仅4人。
王一峰于2018年免试推荐至哈工大深圳校区数学学科，师从赵毅教授，先后获得数学硕士、博士学位，在读期间两次荣获国家奖学金。博士阶段，他依托课题组在月壤表征领域的长期探索，并充分发挥哈工大作为航天第一校的学科优势，致力于数学及人工智能方法与深空探测的深度融合。在复杂受限环境物理感知、月面数据智能处理等方向取得突出成果，以第一作者发表学术论文14篇，获授权国家发明专利15项。其博士学位论文先后获评哈工大优秀博士学位论文、大湾区优秀博士学位论文特等奖、深圳市人工智能学会优秀博士论文；个人获评黑龙江省优秀毕业生。毕业后，王一峰入选清华大学“水木学者”青年人才计划，现为清华大学计算机系博士后。（编辑 郑佳宜 审核 张惠屏 陈南坤）
王一峰博士使用国家大科学装置采集月壤颗粒数据');
INSERT INTO `campus_news` VALUES ('2026081001', '未来学部举办“和优论坛”第六期邀请国家级青年人才董磊研究员作题为《人群移动行为的普适性规律》主题报告','2026-08-10','https://www.hitsz.edu.cn/_upload/article/images/09/dd/c1d6008649749cdbf0fd79aab9d3/9a79159b-b10e-4482-8c08-cd6d80636e3c.png','未来学部加强教师队伍建设，举办“和优论坛”旨在助力教师发展，凝聚团队力量，促进多学科交流协作，推动人才队伍建设。第六期论坛于近日顺利举行，特邀国家级青年人才、北京大学地球与空间科学学院董磊研究员作题为《人群移动行为的普适性规律》的报告。本期论坛由学部国家级青年人才关金平教授主持。
董磊研究员长期致力于人群移动行为规律的研究，在Nature、Nature Cities、PNAS等国际高质量期刊上累计发表论文三十余篇，在该领域取得了丰硕的科研成果。在本次报告中，董磊研究员围绕人群移动行为的普适性规律，系统阐述了其团队在人类移动模式建模、时空行为特征提取及城市系统演化等方面的最新研究进展，深入探讨了相关规律在城市规划、交通管理及公共卫生等领域的应用前景，为在场教师提供了极具启发性的跨学科研究视角。
在交流互动环节，参会教师结合自身教学科研实际，围绕课题研究、论文发表、跨学科合作等内容踊跃提问、深入探讨。
董磊研究员进行分享
图文马程程
初审张湘妮
复审朱继任
终审张爱书');

-- ----------------------------
