-- 3 讲座论坛（9 条）
UPDATE `campus_news` SET `category` = 3 WHERE `id` IN (2026102801, 2026102201, 2026101501, 2026101401, 2026101201, 2026101001, 2026101002, 2026100801, 2026100802);
-- 4 科创成果（9 条）
UPDATE `campus_news` SET `category` = 4 WHERE `id` IN (2026110301, 2026101902, 2026101502, 2026101301, 2026101003, 2026092801, 2026092802, 2026091802, 2026091401);
-- 5 就业实践（7 条）
UPDATE `campus_news` SET `category` = 5 WHERE `id` IN (2026093001, 2026092301, 2026092302, 2026091801, 2026091601, 2026090601, 2026081001);

-- ----------------------------
-- Table structure for `users`
-- 小程序用户表（用于保存 wx.login 登录后的 openid 与用户资料）
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(12) NOT NULL AUTO_INCREMENT COMMENT '用户序号',
  `openid` varchar(64) NOT NULL COMMENT '微信用户唯一标识',
  `nickname` varchar(60) DEFAULT NULL COMMENT '昵称',
  `avatar` varchar(254) DEFAULT NULL COMMENT '头像地址',
  `create_time` datetime DEFAULT NULL COMMENT '首次登录时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `openid` (`openid`)
) ENGINE=MyISAM DEFAULT CHARSET=gbk COMMENT='小程序用户表';
